{
    double fs;
    double md;
    double vals[3];
    unsigned int promote = 0U;
    unsigned int axis;

    if ((requested_a_m2 == NULL) || (duty == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!isfinite(requested_a_m2->x)) || (!isfinite(requested_a_m2->y)) ||
        (!isfinite(requested_a_m2->z)) || (!isfinite(full_scale_a_m2)) ||
        (!isfinite(minimum_duty))) {
        duty->command = (adcs_vec3_t){0, 0, 0};
        duty->saturated_axes = 0U;
        return ADCS_E_RANGE;
    }
    if ((full_scale_a_m2 <= 0.0) || (minimum_duty < 0.0) || (minimum_duty > 1.0)) {
        duty->command = (adcs_vec3_t){0, 0, 0};
        duty->saturated_axes = 0U;
        return ADCS_E_RANGE;
    }

    duty->command = (adcs_vec3_t){0, 0, 0};
    duty->saturated_axes = 0U;

    fs = full_scale_a_m2;
    md = minimum_duty;

    vals[0] = requested_a_m2->x;
    vals[1] = requested_a_m2->y;
    vals[2] = requested_a_m2->z;

    for (axis = 0U; axis < 3U; axis++) {
        double d;
        double a;
        double mag;
        double s;
        unsigned int bit;

        d = vals[axis] / fs;
        a = fabs(d);
        s = (d < 0.0) ? -1.0 : ((d > 0.0) ? 1.0 : 0.0);
        bit = 0U;

        if (a == 0.0) {
            mag = 0.0;
            bit = 0U;
        } else if (a < md) {
            mag = md;
            bit = 1U;
        } else if (a <= 1.0) {
            mag = a;
            bit = 0U;
        } else {
            mag = 1.0;
            bit = 0U;
        }

        if (bit != 0U) {
            promote |= (unsigned int)(1U << axis);
        }

        if (axis == 0U) {
            duty->command.x = s * mag;
        } else if (axis == 1U) {
            duty->command.y = s * mag;
        } else {
            duty->command.z = s * mag;
        }
    }

    duty->saturated_axes = promote;
    return ADCS_OK;
}
}

